import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface SignUpData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  comment: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
];

const emptyData: SignUpData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  comment: '',
};

export default function SignUpWizard({ onSubmit }: { onSubmit: (data: SignUpData) => void }) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<SignUpData>(emptyData);

  const set = <K extends keyof SignUpData>(key: K, value: SignUpData[K]) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const emailError =
    data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const contactsValid = data.name.trim() !== '' && data.email.includes('@');
  const addressValid = data.country !== '' && data.city.trim() !== '' && data.street.trim() !== '';
  const canGoNext = step === 0 ? contactsValid : step === 1 ? addressValid : true;

  const countryLabel = countries.find((c) => c.value === data.country)?.label ?? '—';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={emailError}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            helperText="Необязательно"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
          />
          <JxTextareaField
            label="Комментарий к адресу"
            rows={3}
            maxLength={300}
            value={data.comment}
            onChange={(event) => set('comment', event.target.value)}
            helperText={`${data.comment.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <JxDivider label="Контакты" />
          <div style={{ color: 'var(--jx-text-2)' }}>Имя: {data.name}</div>
          <div style={{ color: 'var(--jx-text-2)' }}>Почта: {data.email}</div>
          <div style={{ color: 'var(--jx-text-2)' }}>Телефон: {data.phone || '—'}</div>
          <JxDivider label="Адрес" />
          <div style={{ color: 'var(--jx-text-2)' }}>Страна: {countryLabel}</div>
          <div style={{ color: 'var(--jx-text-2)' }}>Город: {data.city}</div>
          <div style={{ color: 'var(--jx-text-2)' }}>Улица и дом: {data.street}</div>
          {data.comment && (
            <div style={{ color: 'var(--jx-text-2)' }}>Комментарий: {data.comment}</div>
          )}
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext} onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

